"""Trusted fixed helpers: Boolean Value(Signaling) and native BD.Get Image Scaled."""
import pathlib,xml.etree.ElementTree as E
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'gui-tools';OUT.mkdir(exist_ok=True)
def base(name):return E.Element('VI',{'_name':name+'.vi','description':'Trusted local GUI verification helper. Operates on the explicit generated VI path only.'})
def el(r,tag,u,**attrs):return E.SubElement(r,tag,dict(attrs,uid=str(u),uid_parent='root'))
def common(r):
 el(r,'Control',1,_name='TargetPath',type='string',value='',outputs='value:1.v');el(r,'Node',2,_name='String To Path',inputs='string:1.v',outputs='path:2.p');el(r,'Node',3,_name='Open VI Reference',inputs='vi path:2.p,error in (no error):',outputs='vi reference:3.ref,error out:3.err')
def err(r,net):
 el(r,'Node',90,_name='Unbundle By Name',fields='status,code',inputs='input cluster:'+net,outputs='status:90.s,code:90.c');el(r,'Indicator',91,_name='Error',type='bool',value='false',inputs='value:90.s');el(r,'Indicator',92,_name='Code',type='int32',value='0',inputs='value:90.c')
r=base('SignalGuiBoolean');common(r)
el(r,'Control',4,_name='ControlName',type='string',value='Start',outputs='value:4.v')
el(r,'Node',5,_name='Property Node',type='{LV.VI}',fields='read+Front Panel',inputs='reference:3.ref,error in (no error):3.err',outputs='Front Panel:5.fp,error out:5.err')
el(r,'Node',6,_name='Property Node',type='{LV.Panel}',fields='read+Controls[]',inputs='reference:5.fp,error in (no error):5.err',outputs='Controls[]:6.cs,error out:6.err')
f=el(r,'Structure',10,_name='For Loop',count='',maxin='',maxout='')
E.SubElement(f,'Tunnel',{'_id':'In1','inputs':'value:6.cs','outputs':'value:11.v','mode':'index','uid':'11','uid_parent':'10'})
E.SubElement(f,'Node',{'_name':'Property Node','type':'{LV.Control}','fields':'read+Label.Text','inputs':'reference:11.v,error in (no error):','outputs':'Label.Text:12.v,error out:','uid':'12','uid_parent':'10'})
E.SubElement(f,'Tunnel',{'_id':'Out1','inputs':'value:12.v','outputs':'value:13.v','mode':'index','uid':'13','uid_parent':'10'})
el(r,'Node',14,_name='Search 1D Array',inputs='1D array:13.v,element:4.v,start index (0):',outputs='index of element:14.i')
el(r,'Node',15,_name='Index Array',inputs='array:6.cs,index:14.i',outputs='element:15.ref')
el(r,'Constant',16,type='bool',value='true',outputs='value:16.v')
el(r,'Node',17,_name='Property Node',type='{LV.Control}',fields='write+Value (Signaling)',inputs='reference:15.ref,error in (no error):6.err,Value (Signaling):16.v',outputs='reference out:,error out:17.err')
err(r,'17.err');(OUT/'SignalGuiBoolean.aixml').write_text(E.tostring(r,encoding='unicode'))
r=base('CaptureGuiDiagram');common(r)
el(r,'Constant',4,type='int32',value='24',outputs='value:4.v');el(r,'Constant',5,type='int32',value='1600',outputs='value:5.v');el(r,'Constant',6,type='int32',value='1100',outputs='value:6.v')
el(r,'Node',7,_name='Invoke Node',type='{LV.VI}',target='BD.Get Image Scaled',inputs='reference:3.ref,error in (no error):3.err,img depth:4.v,max width:5.v,max height:6.v',outputs='img data:7.img,reference out:,error out:7.err')
el(r,'Node',8,_name='Unbundle By Name',fields='image,image depth,Rectangle',inputs='input cluster:7.img',outputs='image:8.img,image depth:8.depth,Rectangle:8.rect')
el(r,'Node',9,_name='Unbundle By Name',fields='left,top,right,bottom',inputs='input cluster:8.rect',outputs='left:9.l,top:9.t,right:9.r,bottom:9.b')
el(r,'Node',10,_name='Subtract',inputs='x:9.r,y:9.l',outputs='x-y:10.w');el(r,'Node',11,_name='Subtract',inputs='x:9.b,y:9.t',outputs='x-y:11.h')
for u,name,t,net in [(20,'Image','array{uint8}','8.img'),(21,'Width','int32','10.w'),(22,'Height','int32','11.h'),(23,'Depth','int32','8.depth')]:el(r,'Indicator',u,_name=name,type=t,value='[]' if 'array' in t else '0',inputs='value:'+net)
err(r,'7.err');(OUT/'CaptureGuiDiagram.aixml').write_text(E.tostring(r,encoding='unicode'))
